from abq_authoring import *
start(2012,'Riverport Indoor Market (RIM) Ltd',6,[5])
add('a','Identify and describe the most appropriate sources of finance to meet the needs of (i) RIM Ltd and (ii) individual stallholders.',20,'business-3-16','sources-of-finance',['Cover both RIM Ltd and the individual stallholders.','The scheme awards 7 marks for long-term finance for RIM Ltd, 7 for short-term finance for stallholders, and 6 for medium-term finance. Medium-term finance can be credited only once, for either RIM Ltd or the stallholders.'],[response(i,label,[('name','Source / type',m[0]),('explain','Explanation',m[1]),('link','Relevant link',m[2])]) for i,(label,m) in enumerate([('Long term · RIM Ltd',[2,3,2]),('Medium term · RIM Ltd OR stallholders',[2,2,2]),('Short term · individual stallholders',[2,3,2])],1)],[17,18])
add('b','Discuss the benefits for the local community, arising from the success of RIM Ltd.',30,'business-5-16','community-benefits-of-local-enterprise',['Discuss three benefits, including at least one economic and one social benefit. Each response carries 10 marks.'],[response(i,label,[('name','Benefit',3),('explain','Explanation',4),('link','Relevant link',3)]) for i,label in enumerate(['Economic benefit','Social benefit','Additional benefit'],1)],[19])
add('c','Evaluate the promotional techniques undertaken by RIM Ltd.',30,'business-4-17','promotional-techniques',['Discuss three promotional techniques for 9 marks each and give an evaluation for the remaining 3 marks.'],[response(i,f'Promotional technique {i}',[('name','Technique',2),('explain','Explanation',4),('link','Relevant link',3)]) for i in [1,2,3]]+[response(4,'Evaluation',[('evaluate','Evaluation',3)])],[20,21])
finish({'A':20,'B':30,'C':30},[17,18,19,20,21],'The paper prints no closed choose-k pool. Finance sources, community benefits and promotional techniques are open examples. Part A requires both RIM Ltd and the stallholders; the scheme permits medium-term finance for either but awards it only once. This is a shared marking allocation rather than a printed choice route, so A remains one task.', ['A(i) and A(ii) cannot be assigned independent fixed totals: the six medium-term marks are shared, so the full 20-mark task remains together.','B requires at least one economic and one social benefit.','The C support notes illustrate four promotional techniques, but no finite selection menu appears in the paper.','Scheme PDF pages are two greater than printed numbers.'])
